import {seedState,uid,icons,money,cents,int,cleanName,validateProduct,stockDelta,computeCart,executeSale,cancelSale,cashBalance,validateImport,cashTypes} from './core.mjs';
import {fiscalState,fiscalStatus,createFiscalDoc,changeFiscalStatus,demoXML,parseIncomingXML,importIncoming,applyIncoming,sampleIncomingXML} from './fiscal-demo.mjs';
// Demonstração browser-only: nenhuma chamada fiscal, cobrança, backend ou conta real.
const DB_NAME='lkz-erp-web-demo-v1',STORE='snapshots',RECORD='demo-state';
const app=document.getElementById('app');
const ui={page:'dashboard',search:'',category:'all',cart:[],modal:null,selectPayment:'pm-pix',payParts:[],mobilePreview:false,tour:false};
let state,db,busy=false,toastTimer=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(v,cls='')=>`<span class="${cls}">${esc(v)}</span>`;
const select=(entries,val)=>entries.map(e=>{const [v,t]=Array.isArray(e)?e:[e.id,e.name];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(t)}</option>`}).join('');
const button=(label,action,id='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${esc(action)}" data-id="${esc(id)}">${label}</button>`;
const linkSite='<a href="https://lacrosetecnologia.com.br" rel="noopener noreferrer" target="_blank">Lacrose Tecnologia</a>';
const categories=()=>state.categories.filter(c=>c.active);
const activeProducts=()=>state.products.filter(p=>p.active);
const product=id=>state.products.find(p=>p.id===id);
const catName=id=>state.categories.find(c=>c.id===id)?.name||'Sem categoria';
const payMethods=()=>state.paymentMethods.filter(m=>m.active);
const cashKinds=()=>state.cashReasons.filter(m=>m.active);
const cartTotal=()=>ui.cart.length?computeCart(ui.cart,state.products).total:0;
const previewNote='<div class="alert"><strong>Somente treinamento:</strong> pagamentos e emissão de documentos são simulações. Nenhum valor é cobrado, nenhum XML fiscal válido é gerado e a SEFAZ não é acessada.</div>';
const stamp=d=>{try{return new Date(d).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}catch{return '—'}};
const toastMessage=(message)=>{const t=document.getElementById('toast');if(!t)return;if(toastTimer)clearTimeout(toastTimer);t.textContent=message;t.hidden=false;toastTimer=setTimeout(()=>{t.hidden=true},10000)};
const tx=(store,mode='readonly')=>db.transaction(store,mode).objectStore(store);
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result)})}
function loadState(){return new Promise((resolve,reject)=>{const r=tx(STORE).get(RECORD);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
function mutate(changer){return new Promise((resolve,reject)=>{let output,error;const transaction=db.transaction(STORE,'readwrite'),store=transaction.objectStore(STORE);transaction.oncomplete=()=>{state=output;render();resolve(output);if('BroadcastChannel'in window){try{const bc=new BroadcastChannel(DB_NAME);bc.postMessage('updated');bc.close()}catch{}}};transaction.onabort=()=>reject(error||transaction.error||Error('Não foi possível salvar.'));transaction.onerror=()=>{};const r=store.get(RECORD);r.onerror=()=>{error=r.error;transaction.abort()};r.onsuccess=()=>{try{const next=structuredClone(r.result||seedState());const result=changer(next);output=result||next;output.updatedAt=new Date().toISOString();store.put(output,RECORD)}catch(e){error=e;transaction.abort()}}})}
const initState=async()=>{db=await openDB();state=await loadState();if(!state){await mutate(d=>d);state=await loadState()} /* legado v0.1 continua íntegro; fiscalDemo é inicializado somente na primeira operação fiscal */};
function pageHeader(title,sub,actions=''){return `<div class="pagehead"><div><h2>${esc(title)}</h2><p class="sub">${esc(sub)}</p></div>${actions}</div>`}
function stat(icon,title,value,foot){return `<div class="card stat"><span class="stat-icon" aria-hidden="true">${icon}</span><span class="name">${esc(title)}</span><span class="number">${esc(value)}</span><span class="foot">${esc(foot)}</span></div>`}
function activity(icon,title,sub,amount='',kind=''){return `<div class="activity"><span class="avatarish" aria-hidden="true">${icon}</span><div class="grow"><strong>${esc(title)}</strong><small>${esc(sub)}</small></div><span class="amount ${kind}">${esc(amount)}</span></div>`}
function dashboard(){const net=state.sales.filter(x=>!x.cancelled),total=net.reduce((n,s)=>n+s.total,0),low=activeProducts().filter(x=>x.stock<=x.minStock),stocks=activeProducts().reduce((n,p)=>n+p.stock,0);const recent=state.sales.slice(0,5);return pageHeader('Bom dia! Seu negócio em foco','Tudo organizado em um só lugar · Jequié/BA',button('＋ Nova venda','nav','pdv','primary'))+
 `<div class="grid4">${stat('💰','Vendas de demonstração',money(total),'Valores fictícios')}${stat('🧾','Vendas registradas',net.length,'Nesta demonstração')}${stat('📦','Unidades em estoque',stocks,'Saldo local fictício')}${stat('⚠️','Produtos em alerta',low.length,'Reposição sugerida')}</div>`+
 `<div class="grid2 mt"><div class="card"><div class="card-title"><strong>Visão de vendas</strong><span class="pill neutral">Ilustrativo</span></div><div class="bars">${[38,46,32,64,58,80,66].map((x,i)=>`<div class="barcol"><div class="bar" style="height:${x}%"></div><span>${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'][i]}</span></div>`).join('')}</div><p class="footnote mt">Gráfico ilustrativo. Os indicadores acima usam as vendas simuladas.</p></div><div class="card"><div class="card-title"><strong>Últimas vendas</strong>${button('Ver todas','nav','sales','soft')}</div>${recent.length?recent.map(x=>activity('🧾','Venda '+x.number,x.cancelled?'Cancelada (demo)':stamp(x.at),money(x.total),x.cancelled?'bad':'good')).join(''):'<div class="empty">Quando você fizer uma venda de teste, ela aparecerá aqui.</div>'}</div></div>`+
 `<div class="callout mt"><div><strong>Experimente vender como no comércio real.</strong><small>Pesquise produtos, escolha pagamento e registre uma venda fictícia.</small></div>${button('Abrir PDV →','nav','pdv','primary')}</div>`;
}
function filteredProducts(){return activeProducts().filter(p=>(ui.category==='all'||p.categoryId===ui.category)&&[p.name,p.barcode,catName(p.categoryId)].join(' ').toLowerCase().includes(ui.search.toLowerCase()))}
function filters(){return `<div class="filters"><button data-action="filter" data-id="all" class="${ui.category==='all'?'active':''}">Todos</button>${categories().map(c=>`<button data-action="filter" data-id="${esc(c.id)}" class="${ui.category===c.id?'active':''}">${esc(c.name)}</button>`).join('')}</div>`}
function productTile(p){const q=ui.cart.filter(x=>x.id===p.id).reduce((n,x)=>n+x.qty*(x.kind==='pack'?p.packSize:1),0);return `<div class="product"><div class="picture">${esc(p.icon)}</div><strong>${esc(p.name)}</strong><small>${p.stock} un. disponíveis${q?' · '+q+' reservadas no carrinho':''}</small><div class="productbottom"><span class="price">${money(p.unitPrice)}</span><button class="plus" data-action="cartadd" data-id="${esc(p.id)}:unit" aria-label="Adicionar unidade de ${esc(p.name)}">+</button></div>${p.packSize>=2?`<button class="btn soft full" data-action="cartadd" data-id="${esc(p.id)}:pack">📦 Pacote c/ ${p.packSize} · ${money(p.packPrice)}</button>`:''}</div>`}
function cartRows(){return ui.cart.map(x=>{const p=product(x.id);if(!p)return '';const pack=x.kind==='pack',price=pack?p.packPrice:p.unitPrice;return `<div class="cart-item"><div class="title">${esc(p.name)}<small>${pack?'Pacote c/ '+p.packSize:'Unidade'} · ${money(price)}</small></div><div class="qty"><button data-action="cartminus" data-id="${esc(p.id)}:${x.kind}" aria-label="Diminuir">−</button><span>${x.qty}</span><button data-action="cartadd" data-id="${esc(p.id)}:${x.kind}" aria-label="Aumentar">+</button></div><strong class="nowrap">${money(price*x.qty)}</strong></div>`}).join('')}
function pdv(){let total=0,error='';try{total=cartTotal()}catch(e){error=e.message}return pageHeader('PDV · Vendas','Rápido, simples e adaptado ao celular',`<span class="pill ${state.cash.open?'':'warn'}">${state.cash.open?'● Caixa aberto':'○ Caixa fechado'}</span>`)+
 `<div class="pos"><section><input class="input" type="search" id="product-search" value="${esc(ui.search)}" placeholder="🔍 Pesquise nome ou código do produto" aria-label="Buscar produto">${filters()}<div class="product-grid">${filteredProducts().map(productTile).join('')||'<div class="empty">Nenhum produto encontrado.</div>'}</div></section>`+
 `<aside class="card"><div class="card-title"><strong>🛒 Carrinho de venda</strong><span class="pill neutral">${ui.cart.reduce((n,i)=>n+i.qty,0)} itens</span></div>${ui.cart.length?cartRows():'<div class="empty">Toque em + para adicionar um produto.</div>'}${error?`<p class="bad">${esc(error)}</p>`:''}<div class="cart-total"><span>Total</span><strong>${money(total)}</strong></div><div class="row wrap">${button('Limpar','cartclear','','')}${button('Finalizar venda →','checkout','','primary')}</div><p class="footnote">Nenhuma NFC-e real é emitida e nenhuma cobrança é efetuada.</p></aside></div>`}
function products(){return pageHeader('Produtos e embalagens','Cadastre, edite, arquive, configure ícones, caixas e pacotes',button('＋ Novo produto','modal','product','primary'))+
 `<div class="card"><div class="between mb"><strong>${activeProducts().length} produtos ativos</strong>${button('Categorias','nav','categories','soft')}</div><div class="tablewrap"><table class="table"><thead><tr><th>Produto</th><th>Categoria</th><th>Unidade</th><th>Pacote</th><th>Estoque</th><th>Ações</th></tr></thead><tbody>${state.products.map(p=>`<tr><td><strong>${esc(p.icon)} ${esc(p.name)}</strong><br><small>${esc(p.barcode)}</small></td><td>${esc(catName(p.categoryId))}</td><td>${money(p.unitPrice)}</td><td>${p.packSize>=2?p.packSize+' un. · '+money(p.packPrice):'—'}</td><td><span class="pill ${p.stock<=p.minStock?'warn':'neutral'}">${p.stock} un.</span></td><td><div class="table-actions">${button('Editar','modal','product:'+p.id)}${button(p.active?'Arquivar':'Reativar','toggleProduct',p.id,'soft')}${button('Excluir','deleteProduct',p.id,'danger')}</div></td></tr>`).join('')}</tbody></table></div></div>`;
}
function categoriesPage(){return pageHeader('Categorias','Organize produtos por famílias de mercadorias',button('＋ Nova categoria','modal','category','primary'))+
 `<div class="card">${state.categories.map(c=>`<div class="activity"><span class="avatarish">📁</span><div class="grow"><strong>${esc(c.name)}</strong><small>${state.products.filter(p=>p.categoryId===c.id&&p.active).length} produtos ativos · ${c.active?'Ativa':'Arquivada'}</small></div>${button('Editar','modal','category:'+c.id)} ${button(c.active?'Arquivar':'Reativar','toggleCategory',c.id,'soft')} ${button('Excluir','deleteCategory',c.id,'danger')}</div>`).join('')}</div>`+
 `<div class="info mt">Uma categoria com produtos não será apagada silenciosamente. Use arquivamento ou transfira os produtos antes de removê-la.</div>`;
}
function stock(){return pageHeader('Estoque','Movimentações em unidade-base, caixa ou pacote',button('Histórico','modal','stockHistory','soft'))+
 `<div class="grid3 mb">${stat('📦','Produtos ativos',activeProducts().length,'Cadastros disponíveis')}${stat('🧮','Saldo de unidades',activeProducts().reduce((n,p)=>n+p.stock,0),'Somadas todas as mercadorias')}${stat('⚠️','Estoque baixo',activeProducts().filter(p=>p.stock<=p.minStock).length,'Itens para reposição')}</div>`+
 `<div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>Produto</th><th>Saldo</th><th>Pacotes possíveis</th><th>Mínimo</th><th>Movimentar</th></tr></thead><tbody>${activeProducts().map(p=>`<tr><td><strong>${esc(p.icon)} ${esc(p.name)}</strong></td><td>${p.stock} un.</td><td>${p.packSize>=2?Math.floor(p.stock/p.packSize)+' x '+p.packSize:'—'}</td><td>${p.minStock}</td><td>${button('Entrada / saída','modal','stock:'+p.id)}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function cashPage(){const moneyBalance=cashBalance(state),ownSales=state.sales.filter(s=>s.session===state.cash.session&&!s.cancelled);const moves=state.cashMovements.filter(x=>x.session===state.cash.session);return pageHeader('Caixa','Abertura, sangria, suprimento e conferência guiada',`<span class="pill ${state.cash.open?'':'warn'}">${state.cash.open?'Aberto':'Fechado'}</span>`)+
 `<div class="grid4 mb">${stat('💵','Dinheiro na gaveta',money(moneyBalance),'Somente valores simulados')}${stat('🧾','Vendas do turno',ownSales.length,'Turno atual')}${stat('💳','Pagamentos digitais',money(ownSales.reduce((sum,s)=>sum+s.payments.filter(p=>p.kind!=='cash').reduce((n,p)=>n+p.amount,0),0)),'Não entram na gaveta')}${stat('🏪','Caixa',state.cash.open?'Aberto':'Fechado','Turno '+state.cash.session)}</div>`+
 `<div class="grid2"><div class="card"><div class="card-title"><strong>Operações do caixa</strong></div>${state.cash.open?`<div class="row wrap mb">${button('＋ Suprimento','modal','cashmove:in','soft')}${button('− Sangria','modal','cashmove:out','soft')}</div>${button('Encerrar caixa','modal','closecash','primary')}`:button('Abrir caixa','modal','opencash','primary')}<p class="footnote">O fechamento nesta Web Demo não faz backup no Google Drive. É uma simulação local.</p></div><div class="card"><div class="card-title"><strong>Movimentações do turno</strong></div>${moves.length?moves.map(m=>activity(m.kind==='in'?'💵':'📤',m.reason,stamp(m.at),`${m.kind==='in'?'+':'−'}${money(m.amount)}`)).join(''):'<div class="empty">Nenhuma movimentação nesse turno.</div>'}</div></div>`;
}
function salesPage(){return pageHeader('Histórico de vendas','Vendas de treinamento e seus documentos demonstrativos',button('Nova venda','nav','pdv','primary'))+
 `<div class="card">${state.sales.length?state.sales.map(s=>`<div class="activity"><span class="avatarish">🧾</span><div class="grow"><strong>Venda #${s.number} ${s.cancelled?'· CANCELADA':''}</strong><small>${stamp(s.at)} · ${s.items.length} itens · ${s.payments.map(p=>esc(p.name)).join(' + ')}</small></div><strong class="nowrap">${money(s.total)}</strong>${s.cancelled?'':button('Simular NFC-e','modal','fiscalCreate:'+s.id,'soft')}${s.cancelled?'':button('Cancelar (demo)','modal','cancel:'+s.id,'danger')}</div>`).join(''):'<div class="empty">Registre uma venda no PDV para iniciar o histórico.</div>'}</div>`;
}
function reports(){const sales=state.sales.filter(s=>!s.cancelled),all=sales.reduce((n,s)=>n+s.total,0),count=sales.length;const byKind=new Map();for(const s of sales)for(const p of s.payments)byKind.set(p.name,(byKind.get(p.name)||0)+p.amount);return pageHeader('Relatórios','Resumo gerencial com dados fictícios',button('Imprimir resumo','print','','soft'))+
 `<div class="report-heading"><strong>${esc(state.branding.company)}</strong><p class="sub">Relatório gerencial demonstrativo · ${new Date().toLocaleDateString('pt-BR')}</p>${state.branding.logo?`<img class="preview-logo" alt="Logo da empresa" src="${esc(state.branding.logo)}">`:''}</div><div class="grid4 mb">${stat('💰','Vendas acumuladas',money(all),'Demonstração local')}${stat('🧾','Vendas',count,'Apenas registradas')}${stat('🛍️','Ticket médio',count?money(Math.round(all/count)):money(0),'Média por venda')}${stat('📦','Estoque total',activeProducts().reduce((n,p)=>n+p.stock,0),'Unidades-base')}</div>`+
 `<div class="grid2"><div class="card"><h3 class="mb">Vendas por pagamento</h3>${[...byKind].length?[...byKind].map(([n,v])=>activity('💳',n,'Vendas de treinamento',money(v))).join(''):'<div class="empty">Sem vendas nesta demonstração.</div>'}</div><div class="card"><h3 class="mb">Produtos com menor estoque</h3>${activeProducts().slice().sort((a,b)=>a.stock-b.stock).slice(0,6).map(p=>activity(p.icon,p.name,catName(p.categoryId),p.stock+' un.',p.stock<=p.minStock?'bad':'')).join('')}</div></div>`;
}
function usersPage(){return pageHeader('Usuários e permissões','Como serão os perfis na versão operacional')+`<div class="grid2"><div class="card"><h3 class="mb">Perfis previstos</h3>${[['👑','Master','Administração integral'],['🧑‍💼','Gerente','Autorizações e relatórios'],['🧾','Operador de caixa','Vendas e caixa'],['📦','Estoquista','Produtos e movimentações'],['📊','Financeiro','Fluxo e conciliações']].map(a=>activity(a[0],a[1],a[2])).join('')}</div><div class="card"><h3 class="mb">Segurança demonstrativa</h3><div class="alert">Esta versão pública <strong>não possui login nem autorização real</strong>. Qualquer visitante pode alterar sua própria demonstração, mas não acessa dados de outras pessoas. As permissões reais serão aplicadas no servidor Windows/SaaS.</div><p class="footnote">Exclusão de usuários com histórico deverá virar desativação, preservando a autoria dos lançamentos.</p></div></div>`}
function fiscal(){
 const f=state.fiscalDemo||{sequence:1,documents:[],incoming:[]},docs=f.documents||[],incoming=f.incoming||[];
 const pending=incoming.filter(x=>x.status==='pending').length;
 return pageHeader('Fiscal / XML — SIMULAÇÃO','Treine emissão, conferência, cancelamento e XML fictícios',button('＋ Simular emissão','modal','fiscalCreate','primary'))+
 `<div class="alert mb fiscal-warning"><strong>⚠️ SEM VALOR FISCAL:</strong> este módulo não gera NF-e/NFC-e válida, não usa A1/CSC, não transmite à SEFAZ, não calcula tributos oficiais e não substitui contabilidade. Use apenas dados fictícios.</div>`+
 `<div class="grid4 mb">${stat('🧾','Documentos DEMO',docs.length,'Sem protocolo SEFAZ')}${stat('✅','Autorizações fictícias',docs.filter(x=>x.status==='authorized').length,'Somente simulação')}${stat('📥','XMLs de entrada',incoming.length,'Arquivos locais')}${stat('🔎','Conferências pendentes',pending,'Não entram no estoque')}</div>`+
 `<div class="grid2"><div class="card"><div class="card-title"><strong>🧾 Emissão de documentos demonstrativos</strong>${button('Nova emissão','modal','fiscalCreate','soft')}</div><p class="sub mb">Selecione uma venda do PDV e simule NFC-e 65 ou NF-e 55. Rejeição, autorização e contingência são fictícias.</p>`+
 (docs.length?docs.map(d=>`<div class="activity"><span class="avatarish">${d.model==='65'?'🛒':'📄'}</span><div class="grow"><strong>${d.model==='65'?'NFC-e':'NF-e'} DEMO #${esc(d.number)}</strong><small>${stamp(d.createdAt)} · ${esc(fiscalStatus[d.status]||'Desconhecido')}</small></div>${button('Abrir','modal','fiscalDoc:'+d.id,'soft')}</div>`).join(''):'<div class="empty">Nenhuma emissão simulada. Faça uma venda no PDV e clique em Nova emissão.</div>')+`</div>`+
 `<div class="card"><div class="card-title"><strong>📥 Importação e conferência de XML</strong>${button('Importar XML','modal','fiscalImport','primary')}</div><div class="row wrap mb">${button('Baixar XML fictício de exemplo','fiscalSample','','soft')}</div><p class="sub mb">O arquivo é lido apenas neste navegador. Não envie XMLs verdadeiros de clientes para demonstrações públicas.</p>`+
 (incoming.length?incoming.map(x=>`<div class="activity"><span class="avatarish">📦</span><div class="grow"><strong>XML #${esc(x.number)} · ${esc(x.supplier)}</strong><small>${x.lines.length} itens · ${x.status==='applied'?'Entrada DEMO registrada':'Conferência pendente'}</small></div>${button('Conferir','modal','fiscalIncoming:'+x.id,'soft')}</div>`).join(''):'<div class="empty">Nenhum XML importado. Baixe o exemplo fictício para experimentar.</div>')+`</div></div>`;
}
function demoReceipt(d,sale){return `<section class="fiscal-receipt"><div class="fiscal-watermark">SEM VALOR FISCAL</div><div class="report-heading"><div><strong>${esc(state.branding.company)}</strong><p class="sub">Comprovante de TREINAMENTO · ${d.model==='65'?'NFC-e':'NF-e'} SIMULADA</p></div>${state.branding.logo?`<img alt="Logo demonstrativo" class="preview-logo" src="${esc(state.branding.logo)}">`:''}</div><p><b>Documento DEMO #${esc(d.number)}</b> · Venda #${esc(sale.number)}</p><p class="sub">${esc(fiscalStatus[d.status])} · ${stamp(d.createdAt)}</p><div class="tablewrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Total fictício</th></tr></thead><tbody>${sale.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}${i.kind==='pack'?' pac.':' un.'}</td><td>${money(i.unitPrice*i.qty)}</td></tr>`).join('')}</tbody></table></div><div class="cart-total"><span>VALOR SIMULADO</span><strong>${money(sale.total)}</strong></div><div class="alert"><strong>SEM CHAVE DE ACESSO, QR CODE OU PROTOCOLO FISCAL.</strong> Não é documento fiscal e não comprova compra.</div></section>`;}
function fiscalModal(type,id){
 if(type==='fiscalCreate'){
  const sales=state.sales.filter(s=>!s.cancelled&&!((state.fiscalDemo?.documents||[]).some(d=>d.saleId===s.id&&d.status!=='cancelled')));
  return {heading:'Simular emissão — NFC-e / NF-e',content:`${previewNote}<form class="form" data-form="fiscalCreate"><div class="field"><label>Venda demonstrativa</label><select class="input" name="saleId" required>${select(sales.map(s=>[s.id,'Venda #'+s.number+' · '+money(s.total)]),id||'')}</select></div><div class="field"><label>Tipo de documento (fictício)</label><select class="input" name="model"><option value="65">NFC-e 65 (simulação)</option><option value="55">NF-e 55 (simulação)</option></select></div><button type="submit" class="btn primary full" ${sales.length?'':'disabled'}>Preparar XML DEMO</button></form>${sales.length?'':'<p class="alert mt">Faça primeiro uma venda demonstrativa no PDV.</p>'}`};
 }
 if(type==='fiscalDoc'){
  const d=state.fiscalDemo?.documents.find(x=>x.id===id),sale=state.sales.find(x=>x.id===d?.saleId);
  if(!d||!sale)return {heading:'Documento indisponível',content:'<p class="alert">Documento não encontrado.</p>'};
  const buttons=d.status==='draft'?`${button('Simular autorização','fiscalStatus',d.id+':authorized','primary')}${button('Simular rejeição','fiscalStatus',d.id+':rejected','soft')}${button('Simular contingência','fiscalStatus',d.id+':contingency','soft')}`:d.status==='rejected'?button('Corrigir / preparar novamente','fiscalStatus',d.id+':draft','soft'):d.status==='contingency'?button('Simular autorização posterior','fiscalStatus',d.id+':authorized','primary'):d.status==='authorized'?button('Simular cancelamento','modal','fiscalCancel:'+d.id,'danger'):'';
  return {heading:`${d.model==='65'?'NFC-e':'NF-e'} DEMO #${d.number}`,content:`${demoReceipt(d,sale)}<div class="row wrap mt fiscal-actions">${buttons}${button('Baixar XML DEMO','fiscalDownload',d.id,'soft')}${button('Imprimir comprovante DEMO','printDemo',d.id,'soft')}</div><p class="footnote">Todos os eventos são inventados. Nenhum XML enviado à SEFAZ, mesmo quando aparecer “autorização fictícia”.</p>`};
 }
 if(type==='fiscalCancel')return {heading:'Cancelar documento fictício',content:`<div class="alert mb">Simula a autorização de cancelamento e estorna a venda e o estoque demonstrativos, em uma só gravação. Não envia eventos à SEFAZ.</div><form class="form" data-form="fiscalCancel"><div class="field"><label>Motivo do cancelamento (treinamento)</label><input class="input" name="reason" maxlength="120" required value="Desistência fictícia do consumidor"></div><label class="row"><input type="checkbox" name="confirm" required> Entendi que é apenas simulação.</label><button type="submit" class="btn danger full">Confirmar cancelamento DEMO</button></form>`};
 if(type==='fiscalImport')return {heading:'Importar XML de exemplo',content:`<div class="alert mb"><strong>Somente demonstração:</strong> use XML fictício e sem dados pessoais. O XML será lido exclusivamente neste dispositivo. DTD/entidades são bloqueadas.</div><form class="form" data-form="fiscalImport"><div class="field"><label>Arquivo .xml (até 512 KB)</label><input type="file" class="input" name="file" accept=".xml,application/xml,text/xml" required></div><button type="submit" class="btn primary full">Ler e conferir XML (sem estoque automático)</button></form>`};
 if(type==='fiscalIncoming'){
  const f=state.fiscalDemo?.incoming.find(x=>x.id===id);
  if(!f)return {heading:'XML indisponível',content:'<div class="alert">Importação não encontrada.</div>'};
  return {heading:'Conferência XML DEMO #'+f.number,content:`<div class="alert mb">Entrada demonstrativa. Nenhuma nota recebida pela SEFAZ. A quantidade só aumenta no estoque após sua confirmação.</div><p class="sub mb">Fornecedor: ${esc(f.supplier)} · ${f.lines.length} itens</p>${f.status==='applied'?`<div class="info">Estoque fictício atualizado em ${stamp(f.appliedAt)}. Segunda entrada bloqueada.</div>`:`<form class="form" data-form="fiscalApply">${f.lines.map((l,i)=>{const best=state.products.find(p=>p.active&&(p.barcode===l.barcode||p.name.toLowerCase()===l.description.toLowerCase()));return `<div class="fiscal-import-line"><strong>${esc(l.description)}</strong><span class="pill neutral">${l.quantity} un.</span><div class="field"><label>Vincular ao produto do estoque</label><select class="input" name="map-${i}" required><option value="">Selecione o produto</option>${select(activeProducts().map(p=>[p.id,p.name]),best?.id||'')}</select></div></div>`}).join('')}<button type="submit" class="btn primary full">Confirmar entrada de estoque DEMO</button></form>`}`};
 }
 return {heading:'Módulo fiscal demonstrativo',content:'<div class="alert">Apenas treinamento.</div>'};
}

function settings(){const b=state.branding;return pageHeader('Personalização e configurações','Marca, pagamentos, sangrias, suprimentos e dados locais',button('Exportar dados demo','export','','soft'))+
 `<div class="grid2"><div class="card"><div class="card-title"><strong>🎨 Identidade visual</strong></div><form class="form" data-form="branding"><div class="field"><label>Nome de exibição da empresa</label><input class="input" name="company" maxlength="90" value="${esc(b.company)}" required></div><div class="field"><label>Tema de cores</label><div class="themegrid">${[['emerald','#078672','Verde'],['indigo','#5653cc','Roxo'],['blue','#176eaf','Azul'],['orange','#b76427','Laranja']].map(x=>`<label class="themechip ${b.theme===x[0]?'active':''}"><span style="background:${x[1]}"></span><input type="radio" name="theme" value="${x[0]}" ${b.theme===x[0]?'checked':''}> ${x[2]}</label>`).join('')}</div></div><div class="field"><label>Logotipo PNG/JPEG (até 1 MB)</label><input class="input" type="file" name="logo" accept="image/png,image/jpeg"></div>${b.logo?`${button('Remover logo','removeLogo','','soft')}<img alt="Logo de demonstração" class="preview-logo" src="${esc(b.logo)}">`:''}<button class="btn primary" type="submit">Salvar aparência</button></form></div>`+
 `<div class="card"><div class="card-title"><strong>💳 Formas de pagamento</strong>${button('＋ Adicionar','modal','payment','soft')}</div>${state.paymentMethods.map(p=>`<div class="activity"><span class="avatarish">${p.kind==='cash'?'💵':p.kind==='pix'?'📲':'💳'}</span><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.kind)} · ${p.active?'Ativa':'Desativada'}</small></div>${button('Editar','modal','payment:'+p.id)}${button(p.active?'Desativar':'Ativar','togglePayment',p.id,'soft')}${button('Excluir','deletePayment',p.id,'danger')}</div>`).join('')}<p class="footnote">A classificação financeira de pagamentos já utilizados não poderá ser alterada.</p></div></div>`+
 `<div class="grid2 mt"><div class="card"><div class="card-title"><strong>💸 Tipos de suprimento e sangria</strong>${button('＋ Adicionar','modal','reason','soft')}</div>${state.cashReasons.map(r=>`<div class="activity"><span class="avatarish">${r.kind==='in'?'📥':'📤'}</span><div class="grow"><strong>${esc(r.name)}</strong><small>${r.kind==='in'?'Suprimento':'Sangria'} · ${r.active?'Ativo':'Desativado'}</small></div>${button('Editar','modal','reason:'+r.id)}${button(r.active?'Desativar':'Ativar','toggleReason',r.id,'soft')}${button('Excluir','deleteReason',r.id,'danger')}</div>`).join('')}</div><div class="card"><h3 class="mb">🔐 Dados no seu navegador</h3><p class="sub">Produtos, caixa, categorias, vendas e aparência são salvos somente neste navegador/dispositivo usando IndexedDB. Não há sincronização entre aparelhos. Limpar os dados do navegador pode apagar tudo.</p><div class="row wrap mt">${button('⬇ Exportar demo','export','','soft')}${button('⬆ Importar demo','modal','import','soft')}${button('↺ Restaurar demo','modal','reset','danger')}</div><p class="footnote">Não use informações financeiras, fiscais ou pessoais reais. O arquivo de exportação não é criptografado.</p></div></div>`;
}
const pages={dashboard,pdv,products,categories:categoriesPage,stock,cash:cashPage,sales:salesPage,reports,users:usersPage,fiscal,settings};
const NAV=[['dashboard','Visão geral','▦'],['pdv','PDV · Vendas','▣'],['cash','Caixa','▤'],['products','Produtos','▥'],['categories','Categorias','📁'],['stock','Estoque','▧'],['sales','Histórico de vendas','🧾'],['reports','Relatórios','📊'],['users','Usuários','♙'],['fiscal','Fiscal / XML','▤'],['settings','Personalização','⚙']];
function navHTML(){return NAV.map(([key,label,icon],i)=>`${i===7?'<div class="nav-group">ADMINISTRAÇÃO</div>':''}<button data-action="nav" data-id="${key}" class="${ui.page===key?'active':''}"><span class="navicon">${icon}</span><span>${label}</span></button>`).join('')}
function modalMarkup(){if(!ui.modal)return '';const [type,id]=ui.modal.split(':');let heading='',content='';if(type.startsWith('fiscal')){const fm=fiscalModal(type,id);return `<div class="modalback" data-action="closeBackdrop"><div class="modal fiscal-modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modalheader"><h2 id="modalTitle">${esc(fm.heading)}</h2><button class="iconbutton" data-action="closeModal" aria-label="Fechar">×</button></div>${fm.content}</div></div>`;}
 switch(type){
 case 'product':{const p=id?product(id):null;heading=p?'Editar produto':'Novo produto';content=`<form class="form" data-form="product"><div class="field"><label>Descrição</label><input class="input" name="name" value="${esc(p?.name||'')}" maxlength="90" required autofocus></div><div class="formgrid"><div class="field"><label>Categoria</label><select name="categoryId" class="input">${select(categories().map(c=>[c.id,c.name]),p?.categoryId)}</select></div><div class="field"><label>Ícone</label><select name="icon" class="input">${select(icons.map(x=>[x,x]),p?.icon||'📦')}</select></div><div class="field"><label>Preço unidade (R$)</label><input class="input" name="price" inputmode="decimal" type="number" step=".01" min="0" required value="${p?(p.unitPrice/100).toFixed(2):'0.00'}"></div><div class="field"><label>Estoque mínimo (un.)</label><input class="input" name="minStock" type="number" min="0" required value="${p?.minStock??5}"></div><div class="field"><label>Unidades por pacote (0 = sem pacote)</label><input class="input" name="packSize" type="number" min="0" required value="${p?.packSize??0}"></div><div class="field"><label>Preço pacote (R$)</label><input class="input" name="packPrice" type="number" step=".01" min="0" required value="${p?(p.packPrice/100).toFixed(2):'0.00'}"></div></div><div class="field"><label>Código interno fictício</label><input class="input" name="barcode" maxlength="40" value="${esc(p?.barcode||'')}" placeholder="Opcional"></div><div class="info">O estoque inicial é zero. Registre entradas em Estoque após cadastrar.</div><button class="btn primary full" type="submit">Salvar produto</button></form>`;break}
 case 'category':{const c=id?state.categories.find(x=>x.id===id):null;heading=c?'Editar categoria':'Nova categoria';content=`<form class="form" data-form="category"><div class="field"><label>Nome</label><input class="input" name="name" value="${esc(c?.name||'')}" maxlength="70" required autofocus></div><button class="btn primary full" type="submit">Salvar categoria</button></form>`;break}
 case 'stock':{const p=product(id);heading='Movimentar estoque';content=`<div class="info mb"><strong>${esc(p.name)}</strong> · Saldo atual: ${p.stock} unidades${p.packSize>=2?' · pacote c/ '+p.packSize:''}</div><form class="form" data-form="stock"><div class="formgrid"><div class="field"><label>Operação</label><select name="direction" class="input"><option value="in">Entrada</option><option value="out">Saída / Perda</option></select></div><div class="field"><label>Unidade</label><select name="kind" class="input"><option value="unit">Unidade</option>${p.packSize>=2?'<option value="pack">Pacote</option>':''}</select></div><div class="field"><label>Quantidade</label><input class="input" name="qty" type="number" min="1" value="1" required></div><div class="field"><label>Motivo</label><input class="input" name="reason" maxlength="100" value="Ajuste demonstrativo" required></div></div><button class="btn primary full" type="submit">Registrar movimentação</button></form>`;break}
 case 'stockHistory':heading='Movimentações de estoque';content=state.stockMovements.length?state.stockMovements.slice(0,25).map(m=>activity(m.units>=0?'📥':'📤',product(m.productId)?.name||'Produto antigo',m.reason+' · '+stamp(m.at),(m.units>0?'+':'')+m.units+' un.')).join(''):'<div class="empty">Sem movimentações.</div>';break;
 case 'opencash':heading='Abrir caixa';content=`<form class="form" data-form="opencash"><div class="field"><label>Dinheiro inicial (R$)</label><input class="input" name="openingFloat" type="number" step=".01" min="0" value="150.00" required></div><div class="info">Esse valor representa apenas o troco inicial da gaveta.</div><button class="btn primary full" type="submit">Confirmar abertura</button></form>`;break;
 case 'closecash':heading='Fechar caixa';content=`<div class="info mb">Saldo esperado em dinheiro: <strong>${money(cashBalance(state))}</strong></div><form class="form" data-form="closecash"><div class="field"><label>Dinheiro contado na gaveta (R$)</label><input class="input" name="counted" type="number" min="0" step=".01" value="${(cashBalance(state)/100).toFixed(2)}" required></div><button class="btn primary full" type="submit">Encerrar caixa de demonstração</button></form><p class="footnote">Sem envio de dados ao Google Drive. Você pode exportar um arquivo local em Personalização.</p>`;break;
 case 'cashmove':{const kind=id;heading=kind==='in'?'Registrar suprimento':'Registrar sangria';const rs=cashKinds().filter(x=>x.kind===kind);content=`<form class="form" data-form="cashmove"><div class="field"><label>Tipo de movimentação</label><select class="input" name="reasonId">${select(rs.map(x=>[x.id,x.name]))}</select></div><div class="field"><label>Valor (R$)</label><input class="input" name="value" type="number" min=".01" step=".01" required value="20.00"></div><div class="field"><label>Observação</label><input class="input" name="note" maxlength="100" placeholder="Opcional"></div><button class="btn primary full" type="submit">Registrar ${kind==='in'?'suprimento':'sangria'}</button></form>`;break;}
 case 'payment':{const p=id?state.paymentMethods.find(x=>x.id===id):null;heading=p?'Editar pagamento':'Adicionar pagamento';content=`<form class="form" data-form="payment"><div class="field"><label>Nome de exibição</label><input class="input" name="name" maxlength="50" value="${esc(p?.name||'')}" required></div><div class="field"><label>Classificação financeira</label><select class="input" name="kind" ${p&&state.sales.some(s=>s.payments.some(x=>x.methodId===p.id))?'disabled':''}>${select([['cash','Dinheiro'],['pix','Pix'],['credit','Crédito'],['debit','Débito'],['other','Outro']],p?.kind||'other')}</select></div>${p&&state.sales.some(s=>s.payments.some(x=>x.methodId===p.id))?'<p class="hint">Tipo bloqueado porque já existem vendas com esse pagamento.</p>':''}<button class="btn primary full" type="submit">Salvar forma de pagamento</button></form>`;break}
 case 'reason':{const r=id?state.cashReasons.find(x=>x.id===id):null;heading=r?'Editar movimentação':'Novo tipo de movimentação';content=`<form class="form" data-form="reason"><div class="field"><label>Nome</label><input class="input" name="name" maxlength="60" value="${esc(r?.name||'')}" required></div><div class="field"><label>Tipo</label><select class="input" name="kind" ${r?'disabled':''}><option value="in" ${r?.kind==='in'?'selected':''}>Suprimento</option><option value="out" ${r?.kind==='out'?'selected':''}>Sangria</option></select></div><button class="btn primary full" type="submit">Salvar tipo</button></form>`;break}
 case 'cancel':heading='Cancelamento gerencial · Demonstração';content=`<div class="alert mb">No ERP real, essa operação exigirá autenticação individual do gerente e validação fiscal. Aqui é apenas uma simulação.</div><form class="form" data-form="cancel"><div class="field"><label>Motivo do cancelamento</label><input class="input" name="reason" maxlength="120" value="Erro na operação de treinamento" required></div><label class="row"><input type="checkbox" name="confirm" required> Confirmo que é apenas uma simulação sem validade fiscal.</label><button class="btn danger full" type="submit">Simular cancelamento</button></form>`;break;
 case 'import':heading='Importar dados de demonstração';content=`<div class="alert mb">Importar substitui a demonstração deste navegador. Não envie dados reais. Faça uma exportação antes.</div><form class="form" data-form="import"><div class="field"><label>Arquivo JSON exportado pela demo</label><input class="input" type="file" name="file" accept="application/json,.json" required></div><button class="btn primary full" type="submit">Importar demonstração</button></form>`;break;
 case 'reset':heading='Restaurar demonstração';content=`<div class="alert mb">Isso apagará todos os produtos, vendas, categorias e movimentações fictícias deste navegador e restaurará os exemplos iniciais.</div>${button('Sim, restaurar dados fictícios','reset','','danger')}`;break;
 case 'checkout':{const total=cartTotal();heading='Finalizar venda · Demonstração';const methods=payMethods();if(!ui.payParts.length&&methods.length)ui.payParts=[{methodId:methods[0].id,amount:total}];const currentSum=ui.payParts.reduce((sum,p)=>sum+p.amount,0);content=`${previewNote}<div class="cart-total"><span>Total da compra</span><strong>${money(total)}</strong></div><form class="form" data-form="checkout"><div class="field"><label>Divida entre formas de pagamento (se necessário)</label>${ui.payParts.map((p,i)=>`<div class="row"><select class="input" name="method-${i}">${select(methods.map(m=>[m.id,m.name]),p.methodId)}</select><input class="input" name="amount-${i}" type="number" min=".01" step=".01" required value="${(p.amount/100).toFixed(2)}" style="max-width:125px"><button class="btn" type="button" data-action="removePay" data-id="${i}" aria-label="Remover pagamento">×</button></div>`).join('')}</div><div class="between"><span class="sub">Total informado: ${money(currentSum)}</span>${button('＋ Dividir','addPay','','soft')}</div><button class="btn primary full" type="submit">Registrar venda de TREINAMENTO</button></form>`;break;}
 }
 return `<div class="modalback" data-action="closeBackdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modalheader"><h2 id="modalTitle">${heading}</h2><button class="iconbutton" data-action="closeModal" aria-label="Fechar">×</button></div>${content}</div></div>`;
}
function render(){if(!state)return;document.documentElement.dataset.theme=state.branding.theme;const label=NAV.find(x=>x[0]===ui.page)?.[1]||'LKZ ERP';const brand=state.branding.logo?`<img class="preview-logo" alt="Logo personalizado" src="${esc(state.branding.logo)}">`:'<div class="brand-mark">LKZ</div>';
 app.innerHTML=`<div class="appbar"><strong>🔒 LKZ ERP WEB DEMO</strong><span>Simulação comercial · Salva apenas neste navegador · Fiscal apenas DEMO</span></div><div class="shell"><aside class="sidebar"><div class="brand">${brand}<div><strong>LKZ ERP</strong><small>${esc(state.branding.company)}</small></div></div><div class="nav-group">NAVEGAÇÃO</div><nav class="nav" aria-label="Módulos">${navHTML()}</nav><div class="nav-footer">🟢 Demo local no navegador<br><span>Nenhuma ligação com ERP instalado, SEFAZ ou banco real</span><p class="mt">Desenvolvido por ${linkSite}</p></div></aside><div class="workspace-shell"><header class="topbar"><div><h1>${esc(label)}</h1><span class="company">${esc(state.branding.company)} · Jequié/BA · Demonstração</span></div><div class="actions"><button class="btn tablet-hide" data-action="toggleMobile">${ui.mobilePreview?'🖥️ Desktop':'📱 Ver mobile'}</button><span class="pill warn tablet-hide">Sem emissão fiscal</span><span class="avatar">LT</span></div></header><main class="workspace" id="workspace">${pages[ui.page]()}</main><footer class="footer">Desenvolvido por ${linkSite} · Uso demonstrativo, sem validade fiscal</footer><nav class="bottomnav" aria-label="Navegação móvel">${[['dashboard','Início','⌂'],['pdv','Vender','▣'],['products','Produtos','📦'],['cash','Caixa','💵'],['fiscal','Fiscal','🧾'],['settings','Ajustes','⚙']].map(([key,name,icon])=>`<button data-action="nav" data-id="${key}" class="${ui.page===key?'active':''}"><span class="navicon">${icon}</span>${name}</button>`).join('')}</nav></div></div><div id="toast" class="toast" role="status" hidden></div>${modalMarkup()}`;
 if(ui.mobilePreview)document.body.classList.add('mobile-preview');else document.body.classList.remove('mobile-preview');
}
function closeModal(){ui.modal=null;ui.payParts=[];render()}
function go(page){ui.page=page;ui.search='';ui.category='all';ui.modal=null;render();window.scrollTo({top:0,behavior:'instant'})}
function safeCartAdd(key,qty){const [id,kind]=key.split(':'),p=product(id);if(!p||!p.active)throw Error('Produto indisponível.');const match=ui.cart.find(x=>x.id===id&&x.kind===kind);if(match)match.qty+=qty;else if(qty>0)ui.cart.push({id,kind,qty});ui.cart=ui.cart.filter(i=>i.qty>0);if(ui.cart.length)computeCart(ui.cart,state.products);render()}
function mustConfirm(message){return window.confirm(message)}
async function handleAction(action,id,target){
 if(action==='nav'){go(id);return}
 if(action==='toggleMobile'){ui.mobilePreview=!ui.mobilePreview;render();return}
 if(action==='filter'){ui.category=id;render();return}
 if(action==='modal'){ui.modal=id;ui.payParts=[];render();return}
 if(action==='closeBackdrop'){if(target.classList.contains('modalback'))closeModal();return}
 if(action==='closeModal'){closeModal();return}
 if(action==='print'){window.print();return}
 if(action==='printDemo'){window.print();return}
 if(action==='fiscalSample'){downloadTextFile('LKZ-Exemplo-Entrada-Sem-Valor-Fiscal.xml',sampleIncomingXML,'application/xml');return}
 if(action==='fiscalDownload'){const d=state.fiscalDemo?.documents.find(x=>x.id===id),sale=state.sales.find(x=>x.id===d?.saleId);if(!d||!sale)throw Error('Documento não encontrado.');downloadTextFile('LKZ-DEMO-'+d.model+'-'+d.number+'.xml',demoXML(d,sale,state.branding.company),'application/xml');return}
 if(action==='fiscalStatus'){const [docId,nextStatus]=id.split(':');await mutate(s=>{changeFiscalStatus(s,docId,nextStatus)});toastMessage('Situação FICTÍCIA atualizada. Nenhuma comunicação com SEFAZ.');return}
 if(action==='cartadd'||action==='cartminus'){const before=structuredClone(ui.cart);try{safeCartAdd(id,action==='cartadd'?1:-1)}catch(e){ui.cart=before;render();throw e}return}
 if(action==='cartclear'){ui.cart=[];render();return}
 if(action==='checkout'){if(!state.cash.open)throw Error('Abra o caixa antes de vender.');const calc=computeCart(ui.cart,state.products);if(!payMethods().length)throw Error('Ative pelo menos um pagamento.');ui.payParts=[{methodId:payMethods()[0].id,amount:calc.total}];ui.modal='checkout';render();return}
 if(action==='addPay'){const form=document.querySelector('[data-form="checkout"]');if(form){ui.payParts=ui.payParts.map((p,i)=>({methodId:form.elements['method-'+i].value,amount:cents(form.elements['amount-'+i].value)}))}if(ui.payParts.length>=5)throw Error('Máximo de cinco partes.');ui.payParts.push({methodId:payMethods()[0]?.id||'',amount:0});render();return}
 if(action==='removePay'){if(ui.payParts.length<=1)throw Error('Mantenha um pagamento.');const form=document.querySelector('[data-form="checkout"]');if(form)ui.payParts=ui.payParts.map((p,i)=>({methodId:form.elements['method-'+i].value,amount:cents(form.elements['amount-'+i].value)}));ui.payParts.splice(Number(id),1);render();return}
 if(action==='deleteProduct'){if(!mustConfirm('Excluir produto somente se estiver sem saldo e sem histórico?'))return;await mutate(s=>{const p=s.products.find(p=>p.id===id);if(!p)throw Error('Produto não encontrado.');if(p.stock!==0||s.stockMovements.some(m=>m.productId===id)||s.sales.some(sale=>sale.items.some(i=>i.productId===id)))throw Error('Produto com saldo ou histórico deve ser arquivado, não excluído.');s.products=s.products.filter(p=>p.id!==id)});toastMessage('Produto sem histórico excluído.');return}
 if(action==='deleteCategory'){if(!mustConfirm('Excluir categoria vazia?'))return;await mutate(s=>{if(s.products.some(p=>p.categoryId===id))throw Error('Transfira ou exclua os produtos vinculados antes de remover a categoria.');if(s.categories.filter(c=>c.active).length<2&&s.categories.find(c=>c.id===id)?.active)throw Error('Mantenha uma categoria ativa.');s.categories=s.categories.filter(c=>c.id!==id)});toastMessage('Categoria vazia excluída.');return}
 if(action==='deletePayment'){if(!mustConfirm('Excluir forma de pagamento não utilizada?'))return;await mutate(s=>{if(s.sales.some(sale=>sale.payments.some(p=>p.methodId===id)))throw Error('Pagamento com histórico deve ser desativado.');const found=s.paymentMethods.find(p=>p.id===id);if(found?.active&&s.paymentMethods.filter(p=>p.active).length===1)throw Error('Mantenha um pagamento ativo.');s.paymentMethods=s.paymentMethods.filter(p=>p.id!==id)});toastMessage('Pagamento sem histórico excluído.');return}
 if(action==='deleteReason'){if(!mustConfirm('Excluir tipo de movimentação não utilizado?'))return;await mutate(s=>{const r=s.cashReasons.find(x=>x.id===id);if(s.cashMovements.some(m=>m.reason===r?.name))throw Error('Tipo com histórico deve ser desativado.');s.cashReasons=s.cashReasons.filter(x=>x.id!==id)});toastMessage('Tipo não utilizado excluído.');return}
 if(action==='toggleProduct'){await mutate(s=>{const p=s.products.find(x=>x.id===id);if(!p)throw Error('Produto não encontrado.');p.active=!p.active;s.audit.unshift({at:new Date().toISOString(),event:'product-status',description:'Produto '+p.name+' '+(p.active?'reativado':'arquivado')})});toastMessage('Situação do produto alterada na demonstração.');return}
 if(action==='toggleCategory'){await mutate(s=>{const c=s.categories.find(x=>x.id===id);if(!c)throw Error('Categoria não encontrada.');if(c.active&&s.products.some(p=>p.categoryId===id&&p.active))throw Error('Arquive ou transfira os produtos ativos antes de arquivar a categoria.');if(c.active&&s.categories.filter(x=>x.active).length===1)throw Error('Mantenha uma categoria ativa.');c.active=!c.active});toastMessage('Categoria atualizada.');return}
 if(action==='togglePayment'){await mutate(s=>{const p=s.paymentMethods.find(x=>x.id===id);if(!p)throw Error('Pagamento não encontrado.');if(p.active&&s.paymentMethods.filter(x=>x.active).length===1)throw Error('É necessário manter um pagamento ativo.');p.active=!p.active});toastMessage('Pagamento atualizado.');return}
 if(action==='toggleReason'){await mutate(s=>{const r=s.cashReasons.find(x=>x.id===id);if(!r)throw Error('Tipo não encontrado.');r.active=!r.active});toastMessage('Operação atualizada.');return}
 if(action==='removeLogo'){await mutate(s=>{s.branding.logo=null});toastMessage('Logo removido da demonstração.');return}
 if(action==='reset'){if(!mustConfirm('Deseja restaurar somente os dados fictícios deste navegador?'))return;await mutate(()=>seedState());ui.cart=[];ui.modal=null;go('dashboard');toastMessage('Demonstração restaurada.');return}
 if(action==='export'){const bytes=JSON.stringify(state,null,2),blob=new Blob([bytes],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='LKZ-ERP-Web-Demo-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toastMessage('Arquivo de demonstração exportado sem criptografia.');return}
}
function downloadTextFile(name,content,type){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function rasterFileData(file){if(!file||!file.size)return null;if(file.size>1024*1024)throw Error('Logo máximo de 1 MB.');const bytes=new Uint8Array(await file.arrayBuffer());const png=bytes.length>8&&[137,80,78,71,13,10,26,10].every((n,i)=>bytes[i]===n),jpg=bytes.length>4&&bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff;if(!png&&!jpg)throw Error('Use apenas um arquivo PNG ou JPEG válido.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file)})}
async function handleForm(form){const type=form.dataset.form,data=new FormData(form),val=n=>String(data.get(n)??'').trim(),modal=ui.modal,[kind,id]=modal?.split(':')||[];
 if(type==='fiscalCreate'){const saleId=val('saleId'),model=val('model');await mutate(s=>{createFiscalDoc(s,saleId,model)});closeModal();go('fiscal');toastMessage('Documento DEMO criado, sem valor fiscal.');return}
 if(type==='fiscalCancel'){if(!data.get('confirm'))throw Error('Confirme que é somente uma simulação.');await mutate(s=>{changeFiscalStatus(s,id,'cancelled',val('reason'))});closeModal();go('fiscal');toastMessage('Cancelamento simulado com estorno de treinamento.');return}
 if(type==='fiscalImport'){const file=data.get('file');if(!(file instanceof File)||!file.size||file.size>512*1024)throw Error('Selecione XML de até 512 KB.');const bytes=await file.arrayBuffer(),xml=new TextDecoder('utf-8',{fatal:true}).decode(bytes),parsed=parseIncomingXML(xml);const digest=await crypto.subtle.digest('SHA-256',bytes);const hash=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');await mutate(s=>{importIncoming(s,parsed,hash)});closeModal();go('fiscal');toastMessage('XML DEMO importado para conferência; estoque preservado.');return}
 if(type==='fiscalApply'){const incoming=state.fiscalDemo?.incoming.find(x=>x.id===id);if(!incoming)throw Error('XML não encontrado.');const mapping=incoming.lines.map((_,i)=>val('map-'+i));await mutate(s=>{applyIncoming(s,id,mapping)});closeModal();go('fiscal');toastMessage('Entrada fictícia conferida e aplicada ao estoque.');return}
 if(type==='product'){const p={name:cleanName(val('name')),categoryId:val('categoryId'),icon:val('icon'),unitPrice:cents(val('price')),minStock:int(val('minStock')),packSize:int(val('packSize')),packPrice:cents(val('packPrice')),barcode:val('barcode'),active:true};if(!icons.includes(p.icon))throw Error('Ícone inválido.');if(p.packSize===1)throw Error('Pacote exige no mínimo 2 unidades.');if(!p.packSize)p.packPrice=0;await mutate(s=>{if(!s.categories.some(c=>c.id===p.categoryId&&c.active))throw Error('Categoria indisponível.');const old=id?s.products.find(x=>x.id===id):null;const obj={...p,id:old?.id||uid(),stock:old?.stock??0,active:old?.active??true};validateProduct(obj);if(old)Object.assign(old,obj);else s.products.push(obj);s.audit.unshift({at:new Date().toISOString(),event:'product',description:'Produto '+obj.name+' salvo'})});closeModal();toastMessage('Produto salvo neste navegador.');return}
 if(type==='category'){const name=cleanName(val('name'),70);await mutate(s=>{const exist=s.categories.find(c=>c.id===id);if(s.categories.some(c=>c.id!==id&&c.name.toLowerCase()===name.toLowerCase()))throw Error('Esta categoria já existe.');if(exist)exist.name=name;else s.categories.push({id:uid(),name,active:true})});closeModal();toastMessage('Categoria salva.');return}
 if(type==='stock'){const qty=int(val('qty'),1),direction=val('direction'),unit=val('kind'),reason=cleanName(val('reason'),100);await mutate(s=>{const p=s.products.find(x=>x.id===id&&x.active);if(!p)throw Error('Produto indisponível.');const result=stockDelta(p.stock,qty,p.packSize,unit,direction);p.stock=result.next;s.stockMovements.unshift({id:uid(),at:new Date().toISOString(),productId:p.id,units:result.units,reason});s.audit.unshift({at:new Date().toISOString(),event:'stock',description:'Movimentação '+reason})});closeModal();toastMessage('Estoque atualizado no navegador.');return}
 if(type==='opencash'){const openingFloat=cents(val('openingFloat'));await mutate(s=>{if(s.cash.open)throw Error('Caixa já aberto.');s.cash={open:true,session:s.cash.session+1,openingFloat,openedAt:new Date().toISOString(),closedAt:null};s.audit.unshift({at:s.cash.openedAt,event:'cash-open',description:'Caixa demo aberto'})});closeModal();toastMessage('Caixa demonstrativo aberto.');return}
 if(type==='closecash'){const counted=cents(val('counted'));await mutate(s=>{if(!s.cash.open)throw Error('Caixa fechado.');const expected=cashBalance(s);s.cash.open=false;s.cash.closedAt=new Date().toISOString();s.audit.unshift({at:s.cash.closedAt,event:'cash-close',description:'Caixa encerrado (demo). Diferença: '+money(counted-expected)})});closeModal();toastMessage('Caixa demonstrativo encerrado. Nenhum backup enviado ao Google Drive.');return}
 if(type==='cashmove'){const amount=cents(val('value'));if(amount===0)throw Error('Informe um valor maior que zero.');const why=val('note');await mutate(s=>{if(!s.cash.open)throw Error('Abra o caixa.');const r=s.cashReasons.find(r=>r.id===val('reasonId')&&r.active&&r.kind===id);if(!r)throw Error('Tipo de movimentação indisponível.');if(r.kind==='out'&&amount>cashBalance(s))throw Error('Saldo em dinheiro insuficiente.');s.cashMovements.unshift({id:uid(),at:new Date().toISOString(),kind:r.kind,amount,session:s.cash.session,reason:r.name,note:why});s.audit.unshift({at:new Date().toISOString(),event:'cash-move',description:r.name})});closeModal();toastMessage('Movimentação salva.');return}
 if(type==='payment'){const name=cleanName(val('name'),50),paymentKind=id&&form.elements.kind.disabled?state.paymentMethods.find(x=>x.id===id)?.kind:val('kind');if(!cashTypes.includes(paymentKind))throw Error('Tipo financeiro inválido.');await mutate(s=>{const old=id?s.paymentMethods.find(m=>m.id===id):null;if(old){if(s.sales.some(sale=>sale.payments.some(p=>p.methodId===id))&&old.kind!==paymentKind)throw Error('Classificação bloqueada pelo histórico.');old.name=name;old.kind=paymentKind}else s.paymentMethods.push({id:uid(),name,kind:paymentKind,active:true})});closeModal();toastMessage('Forma de pagamento salva.');return}
 if(type==='reason'){const name=cleanName(val('name'),60),newKind=id?state.cashReasons.find(x=>x.id===id)?.kind:val('kind');if(!['in','out'].includes(newKind))throw Error('Tipo inválido.');await mutate(s=>{const old=id?s.cashReasons.find(r=>r.id===id):null;if(old)old.name=name;else s.cashReasons.push({id:uid(),name,kind:newKind,active:true})});closeModal();toastMessage('Tipo de movimento salvo.');return}
 if(type==='cancel'){if(state.fiscalDemo?.documents.some(d=>d.saleId===id&&d.status!=='cancelled'))throw Error('Esta venda possui documento DEMO. Faça o cancelamento pela Central Fiscal.');if(!data.get('confirm'))throw Error('Confirme que é uma simulação.');const reason=cleanName(val('reason'),120);await mutate(s=>cancelSale(s,id,reason));closeModal();toastMessage('Cancelamento fictício registrado; não houve evento fiscal.');return}
 if(type==='branding'){const company=cleanName(val('company')),theme=val('theme');if(!['emerald','indigo','blue','orange'].includes(theme))throw Error('Cor inválida.');const logo=await rasterFileData(data.get('logo'));await mutate(s=>{s.branding.company=company;s.branding.theme=theme;if(logo)s.branding.logo=logo});toastMessage('Personalização salva no navegador.');return}
 if(type==='checkout'){const parts=ui.payParts.map((p,i)=>({methodId:String(form.elements['method-'+i].value),amount:cents(form.elements['amount-'+i].value)}));const cart=structuredClone(ui.cart);await mutate(s=>executeSale(s,cart,parts).next);ui.cart=[];closeModal();go('sales');toastMessage('Venda fictícia registrada com baixa de estoque. Nenhuma NFC-e emitida.');return}
 if(type==='import'){const file=data.get('file');if(!(file instanceof File)||!file.size||file.size>2e6)throw Error('Arquivo inválido ou maior que 2 MB.');const json=JSON.parse(await file.text());validateImport(json);if(json.branding?.logo&&(!/^data:image\/(png|jpeg);base64,/.test(json.branding.logo)||json.branding.logo.length>1500000))throw Error('Logo inválido no arquivo.');if(!mustConfirm('Substituir os dados fictícios deste navegador?'))return;await mutate(()=>json);ui.cart=[];closeModal();go('dashboard');toastMessage('Dados de demonstração importados.');return}
}
app.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||!app.contains(target))return;try{await handleAction(target.dataset.action,target.dataset.id,target===e.target?target:e.target)}catch(err){toastMessage(err.message||'Falha na operação demonstrativa.')}});
app.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(busy)return;busy=true;try{await handleForm(form)}catch(err){toastMessage(err.message||'Não foi possível salvar.')}finally{busy=false}});
app.addEventListener('input',e=>{if(e.target.id!=='product-search')return;const selection=e.target.selectionStart;ui.search=e.target.value;render();const input=document.getElementById('product-search');input?.focus();try{input?.setSelectionRange(selection,selection)}catch{}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal)closeModal()});
(async()=>{try{await initState();render();if('serviceWorker'in navigator&&location.protocol==='https:'){navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{})}if('BroadcastChannel'in window){const bc=new BroadcastChannel(DB_NAME);bc.onmessage=async()=>{if(!busy){state=await loadState();render()}}}}catch(err){app.replaceChildren();const box=document.createElement('div');box.className='boot';const title=document.createElement('strong');title.textContent='Não foi possível iniciar o armazenamento local.';const p=document.createElement('p');p.textContent='Verifique se o navegador permite IndexedDB e armazenamento local. Erro: '+(err.message||'desconhecido');box.append(title,p);app.append(box)}})();